  te_224tmp:function(){return semi([A('CH₃'),A('C',{u:'CH₃',d:'CH₃'}),A('CH₂'),A('CH',{u:'CH₃'}),A('CH₃')],'2,2,4-trimetilpentano');},
  te_4hidroxibutan2ona:function(){return semi([A('CH₃'),A('C',{u:'O',ub:2}),A('CH₂'),A('CH₂'),A('OH')],'4-hidroxibutan-2-ona');},
  te_3cloropropanal:function(){return semi([A('Cl'),A('CH₂'),A('CH₂'),A('CHO')],'3-cloropropanal');},
  /* cicloalcanos */
  te_ciclopropano:function(){return anillo(3,{},'ciclopropano');},
