  te_13dmcp:function(){return anillo(5,{sub:{0:'CH₃',2:'CH₃'}},'1,3-dimetilciclopentano');},
  te_1e2mcp:function(){return anillo(5,{sub:{0:'CH₂−CH₃',1:'CH₃'}},'1-etil-2-metilciclopentano');},
  te_1e3mch:function(){return anillo(6,{sub:{0:'CH₂−CH₃',2:'CH₃'}},'1-etil-3-metilciclohexano');},
  te_124tmch:function(){return anillo(6,{sub:{0:'CH₃',1:'CH₃',3:'CH₃'}},'1,2,4-trimetilciclohexano');},
