  te_clorociclohexano:function(){return anillo(6,{sub:{0:'Cl'}},'clorociclohexano');},
  /* fenoles */
  te_fenol:function(){return anillo(6,{arom:true,sub:{0:'OH'}},'fenol');},
  te_2metilfenol:function(){return anillo(6,{arom:true,sub:{0:'OH',1:'CH₃'}},'2-metilfenol');},
  te_3metilfenol:function(){return anillo(6,{arom:true,sub:{0:'OH',2:'CH₃'}},'3-metilfenol');},
